examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var workspaceName = {{sections.0.row.value}}
@State private var digest = {{sections.1.row.on}}

private func settingsLink(_ title: String, isOpen: Bool, isDanger: Bool) -> some View {
    Button {} label: {
        Text(title)
            .monarchTextStyle(.label)
            .foregroundStyle(isDanger || isOpen ? theme.colors.dangerStrong : theme.colors.textMuted)
            .padding(.horizontal, theme.spacing.space3)
            .frame(maxWidth: .infinity, minHeight: 44, alignment: .leading)
            .background(isOpen ? theme.colors.dangerSubtle : .clear, in: RoundedRectangle(cornerRadius: theme.radius.md))
    }
    .buttonStyle(.plain)
}

private func settingsCard<Content: View>(
    isDanger: Bool = false,
    @ViewBuilder content: () -> Content
) -> some View {
    content()
        .padding(theme.spacing.space4)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(theme.colors.bgSurface, in: RoundedRectangle(cornerRadius: theme.radius.lg))
        .overlay(
            RoundedRectangle(cornerRadius: theme.radius.lg).strokeBorder(
                isDanger ? theme.colors.dangerBorder : theme.colors.borderSubtle,
                lineWidth: 1
            )
        )
        .overlay(alignment: .leading) {
            if isDanger {
                Rectangle().fill(theme.colors.dangerStrong).frame(width: 3)
            }
        }
        .clipShape(RoundedRectangle(cornerRadius: theme.radius.lg))
}

