examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var selection: String? = "notifications"
@State private var pending: String?
@State private var digest = true
@State private var savedDigest = true
@State private var isAsking = false

private let sections = ["profile": "Workspace profile", "notifications": "Notifications", "danger": "Danger zone"]

private var isDirty: Bool { digest != savedDigest }

/// Changing section with unsaved changes asks first, on iPad and on iPhone.
private var guardedSelection: Binding<String?> {
    Binding(
        get: { selection },
        set: { next in
            if isDirty && next != selection {
                pending = next
                isAsking = true
            } else {
                selection = next
            }
        }
    )
}

examples.code:
NavigationSplitView(
    sidebar: {
        List(selection: guardedSelection) {
            Section {
                Label("Workspace profile", systemImage: "building.2").tag("profile")
                Label("Notifications", systemImage: "bell").tag("notifications")
            }
            Section {
                Label("Danger zone", systemImage: "exclamationmark.triangle")
                    .foregroundStyle(theme.colors.dangerStrong)
                    .tag("danger")
            }
        }
        .navigationTitle("Settings")
        .navigationSplitViewColumnWidth(min: theme.spacing.space24 * 2, ideal: theme.spacing.space24 * 3)
    },
    detail: {
        Form {
            if selection == "notifications" {
                Toggle("Weekly digest", isOn: $digest)
            } else {
                Text("Choose a section").foregroundStyle(theme.colors.textMuted)
            }
        }
        .tint(theme.colors.accentSolid)
        .navigationTitle(sections[selection ?? ""] ?? "Settings")
        .toolbar {
            ToolbarItem(placement: .confirmationAction) {
                Button("Save") { savedDigest = digest }
                    .disabled(!isDirty)
            }
            .monarchFlat()
        }
        .monarchUnsavedChangesGuard(
            isPresented: $isAsking,
            hasChanges: isDirty,
            onSave: { savedDigest = digest },
            onLeave: { reason in
                if reason == .discard { digest = savedDigest }
                selection = pending
                pending = nil
            }
        )
    }
)
.frame(minHeight: theme.spacing.space24 * 4)
